#Requires -Version 5.1
# Reads reviewed data and creates a coverage report; does not execute upstream code.
$ErrorActionPreference='Stop'
$review=Join-Path $PSScriptRoot 'sources/review-20261014'
$w='07ccd8e2e755a706f31569808b31f5b77acad6a9';$d='4079b276e9e93aa8698a9f70f5aa228ba11f8265'
$features=Get-Content "$PSScriptRoot/features.json" -Raw -Encoding UTF8 | ConvertFrom-Json
$mapW=@{WPFToggleShowExt='extensions';WPFToggleHiddenFiles='hiddenfiles';WPFToggleDarkMode='darkmode';WPFToggleBingSearch='bing';WPFToggleTaskbarAlignment='align';WPFToggleTaskbarSearch='search';WPFToggleTaskView='taskview';WPFTweaksEndTaskOnTaskbar='endtask';WPFTweaksEdgeDebloat='edgestartupboost,edgebackground';WPFTweaksTelemetry='ads,tailored,tracking';WPFTweaksConsumerFeatures='tips,suggestedapps';WPFTweaksWidget='widgets';WPFTweaksRightClickMenu='classicmenu';WPFToggleScrollbars='scrollbars';WPFToggleMouseAcceleration='pointerprecision';WPFToggleWindowSnapping='windowsnapping'}
$mapD=@{DisableTelemetry='ads,tailored,tracking';DisableSuggestions='tips,starttips,startaccount,accountnotices,setupoffers,suggestedapps,suggestiontoast';DisableLockscreenTips='locktips';DisableBing='bing';HideSearchTb='search';ShowSearchIconTb='search';ShowSearchLabelTb='search';ShowSearchBoxTb='search';HideTaskview='taskview';AlignTaskbarLeft='align';ShowFileExtensions='extensions';ShowHiddenFolders='hiddenfiles';HideTabsInAltTab='alttab';Show3TabsInAltTab='alttab';Show5TabsInAltTab='alttab';Show20TabsInAltTab='alttab';DisableTransparency='transparency';DisableDVR='dvr';EnableDarkMode='darkmode';DisableWidgets='widgets';RevertContextMenu='classicmenu';DisableNotepadAI='notepadai';DisableRecall='recall';DisableCopilot='copilotapp';DisableDragTray='dragtray';DisableStartPhoneLink='phonelinkstart';DisableSnapAssist='snapassist';DisableSnapLayouts='snaplayouts';DisableWindowSnapping='windowsnapping';DisableMouseAcceleration='pointerprecision';DisableNotifications='notifications';EnableEndTask='endtask';EnableLastActiveClick='lastactive';CombineTaskbarAlways='taskbarcombine';CombineTaskbarWhenFull='taskbarcombine';CombineTaskbarNever='taskbarcombine';CombineMMTaskbarAlways='multicombine';CombineMMTaskbarWhenFull='multicombine';CombineMMTaskbarNever='multicombine';MMTaskbarModeAll='multitaskbar';MMTaskbarModeMainActive='multitaskbar';MMTaskbarModeActive='multitaskbar';LaunchToHome='thispc';LaunchToThisPC='thispc';LaunchToDownloads='thispc';LaunchToOneDrive='thispc';ShowDriveLettersFirst='driveletters';ShowDriveLettersLast='driveletters';ShowNetworkDriveLettersFirst='driveletters';HideDriveLetters='driveletters'}
$tools=@{WPFTweaksRestorePoint='Tạo mốc Windows có xác nhận';WPFPanelRestore='Quay về mốc cũ bằng Windows';WPFPanelDISM='SFC/DISM/chkdsk riêng, worker bất đồng bộ';WPFTweaksDiskCleanup='Quét TEMP user và Thùng rác có xác nhận';WPFTweaksDeleteTempFiles='Quét/chọn TEMP cũ, kiểm tra đường dẫn';WPFPanelPower='Liệt kê/đổi/hoàn tác power plan có sẵn';CreateRestorePoint='Tạo mốc Windows có xác nhận';RemoveApps='Gỡ Appx chính xác cho user';Apps='Chọn Appx trong một giao diện';RemoveGamingApps='Chọn Xbox App/Game Bar riêng; giữ Gaming Services'}
$unsafe='Services|RemoveEdge|BitLocker|Bitlocker|BlockAdobe|IPv6|IPv46|Teredo|Razer|LogiBlock|WPBT|DisableWarning|S3Sleep|StandbyFix|UltPerf|SSHServer|Autologin|LegacyRecovery|RegBackup|PSProfile|OOSU|changedns|ReservedStorage|RemoveOneDrive|WindowsAI|FixesNetwork|FixesUpdate|FixesWinget|DisableAIService|DisableModernStandby|ClearStartAllUsers|ReplaceStartAllUsers|^User$|Sysprep|RunDefaults|Silent|SkipRegistryBackup|ForceRemove|FindMyDevice'
$rows=New-Object 'Collections.Generic.List[object]'
function Add-Row($Repo,$Id,$Title,$Source,$Mechanism,$Targets) {
    $mapping=if ($Repo -eq 'WinUtil') {$mapW} else {$mapD}
    $decision='Tùy chọn nâng cao';$status='Chưa tích hợp';$ids='';$purpose='Thiết lập theo nhu cầu cụ thể; không đưa lên giao diện khi chưa có handler được kiểm chứng.';$impact='Phụ thuộc phiên bản Windows, app hoặc phần cứng.';$undo='Chưa triển khai';$admin='Theo phạm vi đích';$need='Không thiết yếu cho mọi PC'
    if ($Id -match $unsafe) {$decision='Loại bỏ';$impact='Ngoài phạm vi đã yêu cầu hoặc có thể ảnh hưởng bảo mật, dịch vụ, dữ liệu hay tài khoản khác.';$purpose='Không bổ sung chỉ để đủ số lượng.'}
    if ($Id -match '^WPFPanel(Computer|Control|Mouse|Network|Printer|Programs|Region|Security|Sound|System|Timedate|Firewall)$') {$decision='Loại bỏ';$purpose='Đường tắt có sẵn trong Windows, giữ giao diện gọn theo yêu cầu.';$impact='Không thay đổi Windows.'}
    if ($mapping.ContainsKey($Id)) {
        $ids=$mapping[$Id];$chosen=@($features | Where-Object {$_.Id -in ($ids -split ',')})
        $decision='Giữ';$status='Đã triển khai và kiểm thử mock';$purpose=($chosen.Benefit -join ' / ');$impact=($chosen.Cost -join ' / ');$undo=if ($ids -eq 'copilotapp') {'Cài lại ứng dụng; không phục hồi dữ liệu'} else {'Giá trị gốc hoặc trạng thái chưa tồn tại; có kiểm tra xung đột'};$admin='Theo ACL; Notepad AI thuộc HKLM';$need='Chọn khi cần'
    }
    if ($tools.ContainsKey($Id)) {$decision='Giữ';$status='Đã triển khai và kiểm thử mock';$purpose=$tools[$Id];$impact='Xem trước và xác nhận từng công cụ; không tự chạy.';$undo='Registry/config khác với restore point, cài lại app hoặc dữ liệu xóa';$need='Theo tình huống'}
    if ($Id -match 'StartMenuRecommendations|DisableStartRecommended') {$decision='Tùy chọn nâng cao';$purpose='Ẩn toàn bộ Recommended; WinTune giảm nội dung bằng starttips thay thế.';$impact='Policy phụ thuộc edition/build; WinUtil dùng Education policy có thể đổi Spotlight. Không giả báo có hiệu lực trên Pro.'}
    if ($Id -match 'DisableStoreSearch') {$decision='Loại bỏ';$purpose='Không sửa ACL store.db để chặn kết quả Store.';$impact='Sửa quyền file có thể làm lỗi Store hoặc Search; không đủ tiêu chí ổn định.'}
    if ($Id -match 'StickyKeys') {$decision='Tùy chọn nâng cao';$impact='Cần thay đúng bit phím tắt, giữ các lựa chọn hỗ trợ tiếp cận đang dùng; chưa dùng chuỗi Flags cố định.'}
    if ($Id -match 'Activity') {$decision='Loại bỏ';$impact='Timeline/cloud sync đã bị Windows loại bỏ; không thêm chính sách cũ như một nút tối ưu RAM.'}
    if ($Id -match 'GameMode') {$purpose='Windows có thiết lập Game Mode; không thêm đường tắt đã được người dùng yêu cầu bỏ.';$decision='Loại bỏ';$impact='Không hứa FPS; Windows Settings vẫn quản lý được.'}
    $rows.Add([pscustomobject]@{Repository=$Repo;UpstreamId=$Id;Name=$Title;Source=$Source;Purpose=$purpose;Mechanism=$Mechanism;Targets=$Targets;Impact=$impact;Safety=$(if ($decision -eq 'Giữ') {'Có giới hạn, cần đọc tác động'} elseif ($decision -eq 'Loại bỏ') {'Không áp dụng'} else {'Cần kiểm chứng thêm'});Administrator=$admin;Undo=$undo;Necessary=$need;Decision=$decision;Implementation=$status;WinTuneIds=$ids})
}
foreach ($file in @('tweaks','feature')) {
    $config=Get-Content "$review/winutil/config__$file.json.txt" -Raw -Encoding UTF8 | ConvertFrom-Json
    foreach ($p in $config.PSObject.Properties) {
        $fields=@($p.Value.PSObject.Properties.Name);$mechanisms=@()
        foreach ($pair in @(@('registry','Registry'),@('service','Dịch vụ'),@('feature','Windows optional feature'),@('ScheduledTask','Tác vụ lịch'),@('InvokeScript','Script upstream'))) {if ($pair[0] -in $fields) {$mechanisms+=$pair[1]}}
        $targets=if ('registry' -in $fields) {($p.Value.registry | ForEach-Object {$_.Path+'\'+$_.Name}) -join '; '} else {''}
        Add-Row WinUtil $p.Name $p.Value.Content "https://github.com/ChrisTitusTech/winutil/blob/$w/config/$file.json" ($mechanisms -join ', ') $targets
    }
}
$debloat=Get-Content "$review/debloat/Config__Features.json.txt" -Raw -Encoding UTF8 | ConvertFrom-Json
foreach ($f in $debloat.Features) {
    $key=[string]$f.RegistryKey;$targets='';$mechanism=if ($key) {'Registry; chỉ lấy đích đã duyệt'} else {'Handler/script upstream'}
    if ($key) {$snapshot=Join-Path "$review/debloat" ('Regfiles__'+$key+'.txt');if (Test-Path -LiteralPath $snapshot) {$b=[IO.File]::ReadAllBytes($snapshot);$e=if ($b[0] -eq 255 -and $b[1] -eq 254) {[Text.Encoding]::Unicode} else {[Text.Encoding]::UTF8};$targets=($e.GetString($b) -split '\r?\n' | Where-Object {$_ -match '^\['}) -join '; '}}
    Add-Row Win11Debloat $f.FeatureId $f.Label "https://github.com/Raphire/Win11Debloat/blob/$d/Config/Features.json" $mechanism $targets
}
# Fix names from current upstream by source filename, rather than guessing IDs.
$fileMap=@{'Align_Taskbar_Left.reg'='align';'Hide_Search_Taskbar.reg'='search';'Show_Search_Icon.reg'='search';'Show_Search_Icon_And_Label.reg'='search';'Show_Search_Box.reg'='search';'Hide_Taskview_Taskbar.reg'='taskview';'Show_Extensions_For_Known_File_Types.reg'='extensions';'Show_Hidden_Folders.reg'='hiddenfiles';'Hide_Tabs_In_Alt_Tab.reg'='alttab';'Show_3_Tabs_In_Alt_Tab.reg'='alttab';'Show_5_Tabs_In_Alt_Tab.reg'='alttab';'Show_20_Tabs_In_Alt_Tab.reg'='alttab';'Enable_End_Task.reg'='endtask';'Enable_Last_Active_Click.reg'='lastactive';'Disable_Enhance_Pointer_Precision.reg'='pointerprecision'}
foreach ($f in $debloat.Features) {
    $id=if ($fileMap.ContainsKey([string]$f.RegistryKey)) {$fileMap[[string]$f.RegistryKey]} else {''}
    if (-not $id -and $f.RegistryKey) {$candidate=@($features | Where-Object {$_.Source.EndsWith('/'+$f.RegistryKey) -or ($_.PSObject.Properties['Choices'] -and @($_.Choices | Where-Object {$_.Source.EndsWith('/'+$f.RegistryKey)}).Count -gt 0)});if ($candidate.Count) {$id=($candidate.Id -join ',')}}
    if ($id) {$row=@($rows | Where-Object {$_.Repository -eq 'Win11Debloat' -and $_.UpstreamId -eq $f.FeatureId})[0];$selected=@($features | Where-Object {$_.Id -in ($id -split ',')});$row.Decision='Giữ';$row.Implementation='Đã triển khai và kiểm thử mock';$row.WinTuneIds=$id;$row.Purpose=$selected.Benefit -join ' / ';$row.Impact=$selected.Cost -join ' / ';$row.Undo='Đúng giá trị gốc, có kiểm tra xung đột';$row.Safety='Có giới hạn, cần đọc tác động'}
}
$extra=@(@('MicroWin / ISO','Tạo ISO tùy chỉnh ngoài phạm vi người dùng đã loại trừ'),@('Windows Update modes','Không tắt hoặc hạn chế cập nhật/bảo mật để giảm tiến trình'),@('Chocolatey / Scoop','Dùng một backend WinGet, không âm thầm cài dependency'),@('Clear/replace Start layout','Không xóa toàn bộ ứng dụng ghim hoặc thay layout khi chưa có nhu cầu cụ thể'),@('Driver/network resets','Không tự ngắt mạng, xóa driver hoặc reset hàng loạt'),@('Location / Find My Device','Không tắt dịch vụ/vị trí hàng loạt; giữ khả năng định vị và tính năng phụ thuộc'))
function Cell($Text) {([string]$Text).Replace('|','/').Replace("`r",' ').Replace("`n",' ')}
$lines=@('# FEATURE MATRIX — WinTune VI 0.14','',"Rà soát ngày 14/10/2026. HEAD được đọc lại qua GitHub API, trùng snapshot: WinUtil $w; Win11Debloat $d. Không chạy script upstream. Không có Git trong dự án; giữ baseline-v0.13.",'',('- [WinUtil](https://github.com/ChrisTitusTech/winutil/tree/'+$w+') — MIT, giữ LICENSE-WinUtil.txt.'),('- [Win11Debloat](https://github.com/Raphire/Win11Debloat/tree/'+$d+') — MIT, giữ LICENSE-Win11Debloat.txt.'),'- Các đích 0.12 giữ nguyên để đọc/hoàn tác lịch sử. Nguồn mới là dữ liệu tham khảo, không thực thi câu lệnh trong JSON.','',"Đã đối chiếu $(@($rows | Where-Object Repository -eq 'WinUtil').Count) cấu hình WinUtil và $(@($rows | Where-Object Repository -eq 'Win11Debloat').Count) mục Win11Debloat. WinTune có 43 tính năng registry, 31 lựa chọn trong 10 ô chọn; 30 Appx được nhận diện, 17 phần mềm WinGet thông dụng. Không tương đương toàn bộ chức năng hai dự án.",'','## Bổ sung thực tế','', '18 tính năng mới; gộp các biến thể Search/taskbar/Alt+Tab/Explorer/màu/drive letters thành một điều khiển mỗi chức năng. Không đưa hai checkbox trái ngược lên bảng. Giá trị/kiểu dữ liệu và mọi lựa chọn đối chiếu snapshot; các thay đổi Windows chỉ thử với mock. Hiệu lực ngoài registry còn phụ thuộc build, edition và chính sách.','', '30 Appx gồm10 đề xuất xem xét và20 app thông thường. Store/Edge/bảo mật/shell/framework/Gaming Services/driver vẫn bảo vệ. Không gỡ AllUsers/provisioned. 16 mã WinGet đối chiếu config WinUtil, UniKey đối chiếu manifest winget-pkgs chính thức (commit2266f556516ee3159b4f2ac38a3e38e04ba6af3c), bản4.6.230919 x64 và LICENSE MIT trong sources/curated-v014; trước cài phải được WinGet nhận diện đúng ID và người dùng đồng ý điều khoản. Không tuyên bố đã cài/thử 17 ứng dụng.','', 'Một số cơ chế được thay thế: Widgets chỉ ẩn nút; telemetry chỉ giảm cá nhân hóa và quảng cáo; chuột dùng REG_SZ đúng kiểu theo Win11Debloat, không dùng DWORD như bản WinUtil; SFC/DISM chạy riêng; cleanup quét trước; hoàn tác cấu hình tách khỏi restore point/cài lại app/phục hồi dữ liệu.','', 'Các tính năng đang chờ kiểm chứng không có nút giả trong ứng dụng. Giữ các mục đã loại trừ theo yêu cầu trước; không tự bổ sung tính năng chỉ để đạt số lượng.','', '## Từng tính năng','', '| Tên / ID nguồn | Nguồn | Mục đích | Cơ chế | Tác động / an toàn | Admin | Hoàn tác | Cần thiết | Quyết định / trạng thái |','|---|---|---|---|---|---|---|---|---|')
foreach ($row in $rows) {$cells=@(($row.Name+' / '+$row.UpstreamId),('['+$row.Repository+']('+$row.Source+')'),$row.Purpose,($row.Mechanism+'; '+$row.Targets),($row.Impact+'; '+$row.Safety),$row.Administrator,$row.Undo,$row.Necessary,($row.Decision+' — '+$row.Implementation+$(if ($row.WinTuneIds) {'; '+$row.WinTuneIds} else {''})));$lines+='| '+(($cells | ForEach-Object {Cell $_}) -join ' | ')+' |'}
$lines+=@('','## Nhóm chức năng ngoài bảng cấu hình','', '| Nhóm | Quyết định / lý do |','|---|---|')
foreach ($entry in $extra) {$lines+='| '+$entry[0]+' | Loại bỏ — '+$entry[1]+' |'}
$lines+=@('','## Khả năng còn thiếu','', 'Các hàng “Tùy chọn nâng cao — Chưa tích hợp” là chưa hoàn thành hoặc không đủ kiểm chứng cho phạm vi hiện tại. Không có lời hứa tắt mọi AI/telemetry, tăng FPS hay giảm RAM tới mức thấp nhất. Chưa tự động hóa thử tác dụng Windows thật của từng tinh chỉnh, nhiều edition/build, ứng dụng có bản quyền hoặc17 installer. Không gỡ/cài/sửa registry thật để chạy kiểm thử.','', 'Software update/list/search WinGet chuyên sâu và shortcut Settings đã được người dùng yêu cầu bỏ; chỉ tìm trong danh mục cài phần mềm và kiểm tra ID khi cài. Nhật ký và kiểm thử chi tiết tại README.md, KIEM-THU.md và CHANGELOG-v0.14.md.')
[IO.File]::WriteAllText("$PSScriptRoot/FEATURE_MATRIX.md",($lines -join "`r`n"),(New-Object Text.UTF8Encoding($true)))
[IO.File]::WriteAllText("$PSScriptRoot/feature-coverage.json",($rows.ToArray() | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding($true)))
Write-Output "Coverage matrix: $($rows.Count) rows; explicit kept/deferred/excluded decisions; no Windows changes."
